package com.cezar.dev.airquality.controllers;
import com.cezar.dev.airquality.dtos.ErrorResponse; import com.cezar.dev.airquality.exceptions.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(InvalidRequestException.class) ResponseEntity<ErrorResponse> invalid(InvalidRequestException e){return error(HttpStatus.BAD_REQUEST,e.getMessage(),"Requisição inválida.");} @ExceptionHandler(MethodArgumentTypeMismatchException.class) ResponseEntity<ErrorResponse> mismatch(){return error(HttpStatus.BAD_REQUEST,"INVALID_COORDINATES","Requisição inválida.");} @ExceptionHandler(CityNotFoundException.class) ResponseEntity<ErrorResponse> missing(){return error(HttpStatus.NOT_FOUND,"CITY_NOT_FOUND","Cidade não encontrada.");} @ExceptionHandler(UpstreamTimeoutException.class) ResponseEntity<ErrorResponse> timeout(){return error(HttpStatus.GATEWAY_TIMEOUT,"UPSTREAM_TIMEOUT","O serviço de clima demorou para responder.");} @ExceptionHandler(UpstreamException.class) ResponseEntity<ErrorResponse> upstream(){return error(HttpStatus.BAD_GATEWAY,"UPSTREAM_ERROR","O serviço de clima está indisponível no momento.");} private ResponseEntity<ErrorResponse> error(HttpStatus s,String c,String m){return ResponseEntity.status(s).body(new ErrorResponse(c,m));} }
